/*
  ESP32 5V two-wire LED strip ON/OFF controller
  Board: ESP32 Dev Module (ESP32-D0WD-V3)

  Hardware: logic-level N-channel MOSFET (recommended), NOT L298N.
  GPIO26 HIGH = strip ON; GPIO26 LOW = strip OFF.
  Serial commands at 115200 baud: ON, OFF, STATUS
*/

const int LED_SWITCH_PIN = 26;

void setStrip(bool on) {
  digitalWrite(LED_SWITCH_PIN, on ? HIGH : LOW);
  Serial.println(on ? "LED STRIP: ON" : "LED STRIP: OFF");
}

void setup() {
  Serial.begin(115200);
  pinMode(LED_SWITCH_PIN, OUTPUT);
  digitalWrite(LED_SWITCH_PIN, LOW); // Safe default: OFF at startup
  delay(200);
  Serial.println("ESP32 LED strip controller ready. Send ON, OFF, or STATUS.");
}

void loop() {
  if (Serial.available()) {
    String command = Serial.readStringUntil('\n');
    command.trim();
    command.toUpperCase();

    if (command == "ON") {
      setStrip(true);
    } else if (command == "OFF") {
      setStrip(false);
    } else if (command == "STATUS") {
      Serial.println(digitalRead(LED_SWITCH_PIN) == HIGH ? "LED STRIP: ON" : "LED STRIP: OFF");
    } else if (command.length() > 0) {
      Serial.println("Unknown command. Use ON, OFF, or STATUS.");
    }
  }
}
